  INSERT INTO simulacao (usuario_id, chat_id, campanha_id, status, etapa, ficha, resultado, modelo, tentativas, criada_em, concluida_em)
  VALUES (v_gabriela_id, 'demo-chat-aguardando', v_camp_id, 'CONCLUIDA', 'Concluída', '{"status": "DRAFT_PENDING_REVIEW", "rule_id": "draft-test-02", "faltantes": [], "parametros": [{"key": "periodo", "type": "date_range", "label": "Prazo da Campanha", "value": {"data_inicio": "2025-11-20", "data_fim": "2025-11-28"}, "options": null, "required": true, "categoria": "REGRA"}, {"key": "pct_acrescimo", "type": "percentage", "label": "Acr\u00e9scimo de Comiss\u00e3o (%)", "value": 1.0, "options": null, "required": true, "categoria": "REGRA"}, {"key": "marcas_alvo", "type": "multi_select", "label": "Marcas Participantes", "value": ["ALL"], "options": [{"id": "ALL", "label": "Todas as Marcas"}, {"id": "10", "label": "PRETO (10)"}, {"id": "20", "label": "BRANCO (20)"}, {"id": "30", "label": "AZUL (30)"}, {"id": "40", "label": "VERMELHO (40)"}, {"id": "50", "label": "AMARELO (50)"}, {"id": "60", "label": "CINZA (60)"}], "required": true, "categoria": "REGRA"}, {"key": "cargos_alvo", "type": "multi_select", "label": "Cargos Eleg\u00edveis", "value": ["100", "200", "300"], "options": [{"id": "100", "label": "VENDEDOR LOJA"}, {"id": "150", "label": "GERENTE"}, {"id": "200", "label": "VENDEDOR BALCAO"}, {"id": "300", "label": "ASSISTENTE DE VENDAS"}], "required": true, "categoria": "REGRA"}, {"key": "meta_vendas", "type": "currency", "label": "Meta Financeira da Campanha (R$)", "value": 2200000.0, "options": null, "required": true, "categoria": "CONSTRAINT"}, {"key": "orcamento_limite", "type": "currency", "label": "Or\u00e7amento M\u00e1ximo de Incentivo (R$)", "value": null, "options": null, "required": false, "categoria": "CONSTRAINT"}], "raw_prompt": "Campanha Virada de Novembro 1% de 20 a 28/11/2025", "tipo_regra": "BONUS_TEMPORARIO"}'::jsonb, '{"meta": {"atingida": true, "diferenca": 300000.0, "meta_vendas": 2200000.0, "vendas_periodo": 2500000.0, "pct_atingimento": 113.64}, "codigo": "import pandas as pd\nimport numpy as np\nfrom datetime import datetime\n\nDATA_INICIO = \"2025-08-01\"\nDATA_FIM = \"2025-08-31\"\nPCT_ACRESCIMO = 1.0\nMARCAS_ALVO = [\"10\", \"20\", \"30\", \"40\", \"50\", \"60\"]\nCARGOS_ALVO = [\"100\", \"200\", \"300\"]\nCOMPETENCIAS = [\"2025-08\"]\n\ndef aplicar_regra(bases, apuracao_base, competencias):\n    vendas = bases[\"vendas\"]\n    \n    # Converter data_venda para datetime para filtragem precisa\n    dt_inicio = pd.to_datetime(DATA_INICIO)\n    dt_fim = pd.to_datetime(DATA_FIM)\n    \n    # Filtrar vendas no per\u00edodo da regra\n    vendas_dt = pd.to_datetime(vendas[\"data_venda\"])\n    mask_vendas = (vendas_dt >= dt_inicio) & (vendas_dt <= dt_fim)\n    vendas_periodo = vendas[mask_vendas].copy()\n    \n    # Garantir tipos texto para os c\u00f3digos\n    for col in [\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]:\n        if col in vendas_periodo.columns:\n            vendas_periodo[col] = vendas_periodo[col].astype(str)\n            \n    apuracao_simulada = apuracao_base.copy()\n    for col in [\"matricula\", \"competencia\", \"cod_loja\", \"cod_marca\", \"cod_cargo\"]:\n        if col in apuracao_simulada.columns:\n            apuracao_simulada[col] = apuracao_simulada[col].astype(str)\n            \n    contribuicoes_list = []\n    \n    # Identificar quem est\u00e1 nas compet\u00eancias simuladas e atende aos crit\u00e9rios de marca e cargo\n    mask_alvo = (\n        apuracao_simulada[\"competencia\"].isin(COMPETENCIAS) &\n        apuracao_simulada[\"cod_marca\"].isin(MARCAS_ALVO) &\n        apuracao_simulada[\"cod_cargo\"].isin(CARGOS_ALVO)\n    )\n    \n    indices_alvo = apuracao_simulada[mask_alvo].index\n    \n    if len(indices_alvo) > 0:\n        # Precisamos calcular a base da regra (vendas na janela) para cada linha afetada\n        # O gerente (cod_cargo ''150'') n\u00e3o est\u00e1 nos CARGOS_ALVO desta regra espec\u00edfica, \n        # mas caso estivesse, a regra diz: \"o GERENTE recebe pct sobre a venda TOTAL da loja no m\u00eas... \n        # some TODAS as vendas da loja (de todos os cargos) na janela; NUNCA filtre as vendas por cod_cargo antes dessa soma.\"\n        # Como CARGOS_ALVO aqui s\u00e3o [\"100\", \"200\", \"300\"], eles recebem sobre a pr\u00f3pria venda no per\u00edodo.\n        # Vamos calcular a venda pr\u00f3pria por (matricula, competencia) e por loja (caso houvesse gerentes).\n        \n        # Vendas pr\u00f3prias por matr\u00edcula e compet\u00eancia no per\u00edodo da regra\n        vendas_proprias = vendas_periodo.groupby([\"matricula\", \"competencia\"], as_index=False)[\"vlr_venda\"].sum()\n        vendas_proprias.rename(columns={\"vlr_venda\": \"venda_periodo_propria\"}, inplace=True)\n        \n        # Juntar com a apura\u00e7\u00e3o simulada\n        apuracao_simulada = apuracao_simulada.merge(\n            vendas_proprias, \n            on=[\"matricula\", \"competencia\"], \n            how=\"left\"\n        )\n        apuracao_simulada[\"venda_periodo_propria\"] = apuracao_simulada[\"venda_periodo_propria\"].fillna(0.0)\n        \n        # Calcular o delta para cada linha\n        # delta = venda_periodo * (PCT_ACRESCIMO / 100)\n        # Nota: Os cargos alvo listados s\u00e3o 100, 200, 300 (vendas pr\u00f3prias).\n        delta_series = np.where(\n            apuracao_simulada.index.isin(indices_alvo),\n            apuracao_simulada[\"venda_periodo_propria\"] * (PCT_ACRESCIMO / 100.0),\n            0.0\n        )\n        \n        delta_arredondado = [round(val, 2) for val in delta_series]\n        apuracao_simulada[\"delta_temp\"] = delta_arredondado\n        \n        # Atualizar comissao\n        nova_comissao = apuracao_simulada[\"comissao\"] + apuracao_simulada[\"delta_temp\"]\n        # Comiss\u00e3o nunca pode ficar negativa\n        apuracao_simulada[\"comissao\"] = np.maximum(nova_comissao, 0.0)\n        \n        # Recalcular delta real aplicado ap\u00f3s restri\u00e7\u00e3o de n\u00e3o negatividade (se houver)\n        # Como o acr\u00e9scimo \u00e9 positivo e comissao base \u00e9 >= 0, comissao final >= 0.\n        \n        # Criar dataframe de contribuicoes para quem teve delta != 0\n        mask_delta = apuracao_simulada[\"delta_temp\"] != 0.0\n        df_contrib_subset = apuracao_simulada[mask_delta].copy()\n        \n        if len(df_contrib_subset) > 0:\n            contribuicoes = pd.DataFrame({\n                \"matricula\": df_contrib_subset[\"matricula\"],\n                \"competencia\": df_contrib_subset[\"competencia\"],\n                \"cod_marca\": df_contrib_subset[\"cod_marca\"],\n                \"cod_cargo\": df_contrib_subset[\"cod_cargo\"],\n                \"elemento_ref\": \"pct_acrescimo\",\n                \"delta\": df_contrib_subset[\"delta_temp\"]\n            })\n            contribuicoes_list.append(contribuicoes)\n            \n        apuracao_simulada.drop(columns=[\"venda_periodo_propria\", \"delta_temp\"], inplace=True)\n\n    if len(contribuicoes_list) > 0:\n        contribuicoes_final = pd.concat(contribuicoes_list, ignore_index=True)\n    else:\n        contribuicoes_final = pd.DataFrame(columns=[\n            \"matricula\", \"competencia\", \"cod_marca\", \"cod_cargo\", \"elemento_ref\", \"delta\"\n        ])\n        \n    return {\n        \"apuracao_simulada\": apuracao_simulada,\n        \"contribuicoes\": contribuicoes_final\n    }\n", "totais": {"baseline": 210000.0, "simulado": 252000.0, "diferenca": 42000.0, "diferenca_pct": 20.0}, "trilha": {"modelo": "gemini-3.5-flash-lite", "passos": [{"dados": null, "ordem": 1, "filtros": "vendas de 01/08/2025 a 31/08/2025; marcas 10, 20, 30, 40, 50, 60", "situacao": "SUCESSO", "tempo_ms": 163, "descricao": "Bases de ago/2025: 465 pessoas no RH, 4982 vendas de 01/08 a 31/08, 24 linhas de % por marca e cargo", "ferramenta": "carregar_bases", "competencias": ["2025-08"], "mensagem_erro": null, "sql_executado": "SELECT f.matricula, to_char(fl.date_ref, ''YYYY-MM'') AS competencia,\n       l.cod_loja, m.cod_marca, c.cod_cargo,\n       f.data_admissao, f.data_demissao\nFROM funcionario f\nJOIN funcionario_loja fl ON fl.funcionario_id = f.id\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = f.id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(fl.date_ref, ''YYYY-MM'') = ANY(%(competencias)s);\nSELECT f.matricula, to_char(v.date_ref, ''YYYY-MM'') AS competencia,\n       v.date_ref AS data_venda, v.vlr_venda::float8 AS vlr_venda,\n       l.cod_loja, m.cod_marca, c.cod_cargo\nFROM venda v\nJOIN funcionario f ON f.id = v.funcionario_id\nJOIN funcionario_loja fl ON fl.funcionario_id = v.funcionario_id\n     AND fl.date_ref = date_trunc(''month'', v.date_ref)::date\nJOIN loja l ON l.id = fl.loja_id\nJOIN marca m ON m.id = l.marca_id\nJOIN funcionario_cargo fc ON fc.funcionario_id = v.funcionario_id AND fc.date_ref = fl.date_ref\nJOIN cargo c ON c.id = fc.cargo_id\nWHERE to_char(v.date_ref, ''YYYY-MM'') = ANY(%(competencias)s);\nSELECT m.cod_marca, c.cod_cargo, mc.pct_comiss::float8 AS pct_comiss\nFROM marca_cargo mc\nJOIN marca m ON m.id = mc.marca_id\nJOIN cargo c ON c.id = mc.cargo_id\nWHERE mc.date_ref = (SELECT max(date_ref) FROM marca_cargo);", "tabelas_acessadas": ["cargo", "funcionario", "funcionario_cargo", "funcionario_loja", "loja", "marca", "marca_cargo", "venda"], "registros_retornados": 5471}, {"dados": null, "ordem": 2, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1867, "descricao": "Comiss\u00e3o atual (regras 5a a 5g): R$ 344.985,40", "ferramenta": "comissao_atual", "competencias": ["2025-08"], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 465}, {"dados": null, "ordem": 3, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 4517, "descricao": "C\u00f3digo gerado por gemini-3.5-flash-lite em 1 tentativa, conferido com o c\u00e1lculo de refer\u00eancia", "ferramenta": "gerar_codigo", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 4, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1065, "descricao": "C\u00f3digo executado no sandbox", "ferramenta": "executar_sandbox", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 465}, {"dados": null, "ordem": 5, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1113, "descricao": "6 confer\u00eancias passaram: colunas obrigat\u00f3rias, mesmas pessoas e meses da comiss\u00e3o atual, sem comiss\u00e3o negativa, contribui\u00e7\u00f5es somam a diferen\u00e7a, escopo da regra, c\u00e1lculo de refer\u00eancia", "ferramenta": "conferir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}, {"dados": null, "ordem": 6, "filtros": null, "situacao": "SUCESSO", "tempo_ms": 1396, "descricao": "Custo adicional de R$ 100.899,77", "ferramenta": "resumir", "competencias": [], "mensagem_erro": null, "sql_executado": null, "tabelas_acessadas": [], "registros_retornados": 0}], "campanhas": [{"nome": "Especifica\u00e7\u00e3o ago/25, item 2h", "tipo": "SUBSTITUICAO", "autor": null, "versao": null, "data_fim": "2025-08-31", "pct_novo": 1.75, "aprovador": null, "aprovada_em": null, "campanha_id": null, "data_inicio": "2025-08-01", "justificativa": "Somente em ago/25, o % da marca 10 no cargo 300 sobe para 1,75%", "pct_acrescimo": null}], "premissas": ["Gerentes (150) exclu\u00eddos", "Cargos eleg\u00edveis: 100, 200, 300", "Marcas inclu\u00eddas: 10, 20, 30, 40, 50, 60", "Per\u00edodo: de 01/08/2025 a 31/08/2025", "Acr\u00e9scimo de comiss\u00e3o: +1.0%", "Simula\u00e7\u00e3o sobre vendas que j\u00e1 aconteceram: sup\u00f5e que as pessoas venderiam o mesmo com a regra nova.", "A compara\u00e7\u00e3o com a comiss\u00e3o atual \u00e9 o n\u00famero mais confi\u00e1vel; o total absoluto \u00e9 apurado por n\u00f3s, n\u00e3o \u00e9 a folha oficial.", "A comiss\