 "2025-11-20", "pct_vigente": 2.5, "pct_com_campanha": 3.5}, {"cargo": "100", "marca": "50", "data_fim": "2025-11-28", "pct_base": 2.5, "historico": [], "data_inicio": "2025-11-20", "pct_vigente": 2.5, "pct_com_campanha": 3.5}, {"cargo": "200", "marca": "50", "data_fim": "2025-11-28", "pct_base": 2.0, "historico": [], "data_inicio": "2025-11-20", "pct_vigente": 2.0, "pct_com_campanha": 3.0}, {"cargo": "300", "marca": "50", "data_fim": "2025-11-28", "pct_base": 1.5, "historico": [], "data_inicio": "2025-11-20", "pct_vigente": 1.5, "pct_com_campanha": 2.5}, {"cargo": "100", "marca": "60", "data_fim": "2025-11-28", "pct_base": 3.0, "historico": [], "data_inicio": "2025-11-20", "pct_vigente": 3.0, "pct_com_campanha": 4.0}, {"cargo": "200", "marca": "60", "data_fim": "2025-11-28", "pct_base": 2.5, "historico": [], "data_inicio": "2025-11-20", "pct_vigente": 2.5, "pct_com_campanha": 3.5}, {"cargo": "300", "marca": "60", "data_fim": "2025-11-28", "pct_base": 2.0, "historico": [], "data_inicio": "2025-11-20", "pct_vigente": 2.0, "pct_com_campanha": 3.0}]}'::jsonb, 'gemini-3.5-flash-lite', 1, '2026-10-25 14:05:00+00', '2026-10-25 14:05:06+00')
