  --------------------------------------------------------------------------
  INSERT INTO campanha (nome, autor_id, chat_id, status, criada_em, atualizada_em)
  VALUES ('Black Friday 2025 - Aprovada', v_gabriela_id, 'demo-chat-aprovada', 'APROVADA', '2026-10-24 16:00:00+00', '2026-10-24 17:15:00+00')
